window.IA = (function () {
  const MESES = ["janeiro","fevereiro","março","abril","maio","junho","julho","agosto","setembro","outubro","novembro","dezembro"];
  const DIAS = ["Domingo","Segunda-feira","Terça-feira","Quarta-feira","Quinta-feira","Sexta-feira","Sábado"];
  const parse = (iso) => { const [y, m, d] = iso.split("-").map(Number); return new Date(y, m - 1, d); };
  const hoje = () => { const t = location.pathname.endsWith(".dc.html") ? new URLSearchParams(location.search).get("hoje") : null; if (t) return t; const d = new Date(); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); };
  const local = location.pathname.endsWith(".dc.html");
  const pagInicio = local ? "Inicio.dc.html" : "index.html";
  const pagReflexao = local ? "Reflexao.dc.html" : "reflexao.html";
  const pagTodas = local ? "Todas as Reflexões.dc.html" : "todas.html";
  function lista() {
    const h = hoje();
    return (window.REFLEXOES || []).filter(r => r.data <= h).sort((a, b) => b.data.localeCompare(a.data));
  }
  function futuras() {
    const h = hoje();
    return (window.REFLEXOES || []).filter(r => r.data >= h).sort((a, b) => a.data.localeCompare(b.data));
  }
  function enfeitar(r) {
    const d = parse(r.data);
    return Object.assign({}, r, {
      dia: DIAS[d.getDay()],
      dataLonga: d.getDate() + " de " + MESES[d.getMonth()] + " de " + d.getFullYear(),
      dataCurta: d.getDate() + " de " + MESES[d.getMonth()],
      href: (local ? pagReflexao + "?d=" + r.data : r.data + ".html") + (new URLSearchParams(location.search).get("hoje") ? "&hoje=" + new URLSearchParams(location.search).get("hoje") : ""),
      oracao: r.oracao.map(t => ({ t })),
      temEvangelho: !!(r.evangelho && r.evangelho.texto),
      bg: "url('" + r.imagem + "')"
    });
  }
  function hojeLonga() { const d = parse(hoje()); return DIAS[d.getDay()] + ", " + d.getDate() + " de " + MESES[d.getMonth()] + " de " + d.getFullYear(); }
  return { hoje, lista, futuras, enfeitar, hojeLonga, pagInicio, pagReflexao, pagTodas };
})();
